-- =============================================================================
-- ABB Plant 3 — Security Gate Verification & ID Management System
-- Migration 0001 — initial schema  (PROPOSAL — not yet applied)
-- =============================================================================
--
-- PORTABILITY CONVENTIONS (so a later move to PostgreSQL is mechanical):
--   * Every primary key is an opaque TEXT id generated by the backend
--     (e.g. UUID). No AUTOINCREMENT / SERIAL / rowid assumptions.
--   * Timestamps are TEXT in ISO-8601 UTC form: 'YYYY-MM-DDTHH:MM:SSZ'.
--     They are set by the backend, not by database functions, so behaviour is
--     identical on SQLite and PostgreSQL.
--   * Date-only values (validity) are TEXT 'YYYY-MM-DD'.
--   * Booleans are INTEGER 0/1 with a CHECK constraint.
--   * Only portable SQL is used: CHECK, FOREIGN KEY, UNIQUE and (partial)
--     INDEX. No SQLite-only syntax, no triggers.
--
-- ENFORCEMENT NOTES (SQLite has no RLS — the backend enforces everything):
--   * `gate_events` and `canteen_events` are APPEND-ONLY. The data-access layer
--     must never issue UPDATE or DELETE against them. Corrections are new rows
--     plus an `audit_log` entry.
--   * `PRAGMA foreign_keys = ON` and `PRAGMA journal_mode = WAL` are applied by
--     the backend when it opens the connection (runtime settings, not schema).
--   * "At most one open entry per person" (a person inside Plant 3 who has not
--     exited) is enforced in a transaction in the data-access layer, because it
--     is a cross-row rule that a unique index cannot express.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Migration bookkeeping
-- ---------------------------------------------------------------------------
CREATE TABLE schema_migrations (
  version     TEXT PRIMARY KEY,
  applied_at  TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Sites (only Plant 3 is exposed; the model allows more plants later)
-- ---------------------------------------------------------------------------
CREATE TABLE plants (
  id          TEXT PRIMARY KEY,
  code        TEXT NOT NULL UNIQUE,          -- e.g. 'P3'
  name        TEXT NOT NULL,                 -- e.g. 'ABB Plant 3'
  created_at  TEXT NOT NULL
);

CREATE TABLE gates (
  id          TEXT PRIMARY KEY,
  plant_id    TEXT NOT NULL REFERENCES plants(id),
  code        TEXT NOT NULL UNIQUE,          -- e.g. 'P3-MAIN'
  name        TEXT NOT NULL,                 -- 'Plant 3 - Main Gate'
  is_active   INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at  TEXT NOT NULL
);

CREATE INDEX ix_gates_plant ON gates (plant_id);

-- ---------------------------------------------------------------------------
-- Users, sessions and settings
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id             TEXT PRIMARY KEY,
  username       TEXT NOT NULL UNIQUE,
  email          TEXT,
  full_name      TEXT NOT NULL,
  password_hash  TEXT NOT NULL,              -- vetted hash (e.g. argon2/bcrypt)
  role           TEXT NOT NULL CHECK (role IN ('administrator', 'security_staff')),
  is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL,
  last_login_at  TEXT
);

-- Stores a HASH of the session token, never the raw token.
CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,            -- hash of the session token
  user_id       TEXT NOT NULL REFERENCES users(id),
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL,
  revoked_at    TEXT,
  last_seen_at  TEXT
);

CREATE INDEX ix_sessions_user ON sessions (user_id);
CREATE INDEX ix_sessions_expires ON sessions (expires_at);

CREATE TABLE settings (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  updated_by  TEXT REFERENCES users(id)
);

-- ---------------------------------------------------------------------------
-- People — contract/temporary workers, internship students, visitors
-- One table with a category discriminator. Category-specific required fields
-- are enforced by CHECK constraints below. Personal data and photographs are
-- kept behind authenticated, permission-checked endpoints.
-- ---------------------------------------------------------------------------
CREATE TABLE people (
  id                  TEXT PRIMARY KEY,
  category            TEXT NOT NULL CHECK (category IN ('worker', 'intern', 'visitor')),
  full_name           TEXT NOT NULL,
  phone               TEXT,
  photo_path          TEXT,                  -- path OUTSIDE the web root
  plant_id            TEXT NOT NULL REFERENCES plants(id),
  status              TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'suspended', 'terminated')),
  -- worker-only
  worker_ref          TEXT,                  -- worker ID or auto-generated unique ID
  contractor_company  TEXT,
  -- intern-only
  institution_name    TEXT,                  -- college / institution
  -- visitor-only
  purpose_of_visit    TEXT,
  person_to_meet      TEXT,
  employee_email      TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  created_by          TEXT REFERENCES users(id),

  -- per-category required fields (satisfies the requirements document)
  CHECK (category <> 'worker'  OR worker_ref IS NOT NULL),
  CHECK (category <> 'intern'  OR institution_name IS NOT NULL),
  CHECK (category <> 'visitor' OR (purpose_of_visit IS NOT NULL AND person_to_meet IS NOT NULL))
);

CREATE INDEX ix_people_category_status ON people (category, status);
CREATE INDEX ix_people_name ON people (full_name);

-- Worker IDs must be unique within a plant (partial index is portable).
CREATE UNIQUE INDEX ux_people_worker_ref
  ON people (plant_id, worker_ref) WHERE worker_ref IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Credentials — the ID card / gate pass. The barcode/QR payload is the opaque
-- credential id, never personal data.
-- ---------------------------------------------------------------------------
CREATE TABLE credentials (
  id          TEXT PRIMARY KEY,              -- opaque barcode / QR payload
  person_id   TEXT NOT NULL REFERENCES people(id),
  kind        TEXT NOT NULL CHECK (kind IN ('id_card', 'gate_pass')),
  valid_from  TEXT NOT NULL,                 -- 'YYYY-MM-DD'
  valid_to    TEXT NOT NULL,                 -- 'YYYY-MM-DD'; valid THROUGH this day
  status      TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'suspended', 'terminated')),
  issued_at   TEXT NOT NULL,
  issued_by   TEXT REFERENCES users(id),
  updated_at  TEXT NOT NULL,
  CHECK (valid_to >= valid_from)
);

CREATE INDEX ix_credentials_person ON credentials (person_id);
CREATE INDEX ix_credentials_valid_to ON credentials (valid_to);

-- ---------------------------------------------------------------------------
-- Gate events — APPEND-ONLY audit of every scan at the gate.
-- ---------------------------------------------------------------------------
CREATE TABLE gate_events (
  id                TEXT PRIMARY KEY,
  credential_id     TEXT REFERENCES credentials(id),   -- NULL when unknown code
  person_id         TEXT REFERENCES people(id),        -- NULL when no record
  gate_id           TEXT NOT NULL REFERENCES gates(id),
  direction         TEXT NOT NULL CHECK (direction IN ('entry', 'exit')),
  result            TEXT NOT NULL
                      CHECK (result IN ('approved', 'rejected', 'unable_to_verify')),
  reason_code       TEXT,                    -- e.g. 'expired', 'suspended', 'not_found'
  reason_text       TEXT,
  occurred_at       TEXT NOT NULL,           -- ISO-8601 UTC
  operator_user_id  TEXT REFERENCES users(id),
  recorded_offline  INTEGER NOT NULL DEFAULT 0 CHECK (recorded_offline IN (0, 1)),
  synced_at         TEXT,
  created_at        TEXT NOT NULL
);

CREATE INDEX ix_gate_events_person_time ON gate_events (person_id, occurred_at);
CREATE INDEX ix_gate_events_occurred ON gate_events (occurred_at);
CREATE INDEX ix_gate_events_result ON gate_events (result);

-- PROVISIONAL duplicate-scan guard. The exact detection window is an open
-- question; this collapses identical approved scans at the same gate/instant
-- to one row and will be adjusted once the window is confirmed.
CREATE UNIQUE INDEX ux_gate_events_dedup
  ON gate_events (credential_id, gate_id, direction, occurred_at)
  WHERE result = 'approved' AND credential_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Canteen events — APPEND-ONLY. Approved entries are limited to ONE per person
-- per local calendar day, enforced at the database level by the partial unique
-- index below so concurrent scans cannot create duplicates.
-- ---------------------------------------------------------------------------
CREATE TABLE canteen_events (
  id                TEXT PRIMARY KEY,
  credential_id     TEXT REFERENCES credentials(id),
  person_id         TEXT REFERENCES people(id),
  entry_date        TEXT NOT NULL,           -- local calendar date 'YYYY-MM-DD'
  result            TEXT NOT NULL
                      CHECK (result IN ('approved', 'rejected', 'unable_to_verify')),
  reason_code       TEXT,
  reason_text       TEXT,
  occurred_at       TEXT NOT NULL,
  operator_user_id  TEXT REFERENCES users(id),
  created_at        TEXT NOT NULL
);

CREATE UNIQUE INDEX ux_canteen_one_per_day
  ON canteen_events (person_id, entry_date)
  WHERE result = 'approved' AND person_id IS NOT NULL;

CREATE INDEX ix_canteen_date ON canteen_events (entry_date);

-- ---------------------------------------------------------------------------
-- Incidents and announcements (preserved from the existing shell)
-- ---------------------------------------------------------------------------
CREATE TABLE incidents (
  id           TEXT PRIMARY KEY,
  title        TEXT NOT NULL,
  description  TEXT,
  severity     TEXT NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status       TEXT NOT NULL DEFAULT 'open'
                 CHECK (status IN ('open', 'investigating', 'closed')),
  person_id    TEXT REFERENCES people(id),
  gate_id      TEXT REFERENCES gates(id),
  reported_by  TEXT REFERENCES users(id),
  occurred_at  TEXT NOT NULL,
  created_at   TEXT NOT NULL
);

CREATE INDEX ix_incidents_occurred ON incidents (occurred_at);

CREATE TABLE announcements (
  id          TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  body        TEXT NOT NULL,
  severity    TEXT NOT NULL DEFAULT 'info'
                CHECK (severity IN ('info', 'warning', 'critical')),
  is_active   INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_by  TEXT REFERENCES users(id),
  created_at  TEXT NOT NULL,
  expires_at  TEXT
);

-- ---------------------------------------------------------------------------
-- Business audit log — kept SEPARATE from diagnostic logs.
-- Never stores passwords, tokens, keys or unnecessary personal data.
-- ---------------------------------------------------------------------------
CREATE TABLE audit_log (
  id             TEXT PRIMARY KEY,
  actor_user_id  TEXT REFERENCES users(id),
  action         TEXT NOT NULL,              -- e.g. 'credential.extend'
  entity_type    TEXT NOT NULL,              -- e.g. 'credential'
  entity_id      TEXT,
  old_value      TEXT,                       -- JSON snapshot (may be NULL)
  new_value      TEXT,                       -- JSON snapshot (may be NULL)
  reason         TEXT,
  occurred_at    TEXT NOT NULL
);

CREATE INDEX ix_audit_entity ON audit_log (entity_type, entity_id);
CREATE INDEX ix_audit_time ON audit_log (occurred_at);

-- ---------------------------------------------------------------------------
-- Email delivery log — successes AND failures, surfaced to administrators.
-- ---------------------------------------------------------------------------
CREATE TABLE notification_log (
  id               TEXT PRIMARY KEY,
  person_id        TEXT REFERENCES people(id),
  credential_id    TEXT REFERENCES credentials(id),
  type             TEXT NOT NULL CHECK (type IN ('expiry_reminder', 'expired_notice')),
  recipient_email  TEXT NOT NULL,
  status           TEXT NOT NULL CHECK (status IN ('sent', 'failed')),
  error_text       TEXT,
  attempted_at     TEXT NOT NULL
);

CREATE INDEX ix_notification_status ON notification_log (status);
CREATE INDEX ix_notification_credential ON notification_log (credential_id);
